h=runpy.run_path('docs/comics/new-gpt-20261105-a-lane2-helper.py');s=h['save'];p=h['panel'];n=h['node'];f=h['flow'];b=h['paths'];i=sys.argv[1]
if i=='q-965':
 s(i,'基本循環中，哪些角色不一定另有？',[p('① 生產者：提供有機養分','依本題模型，生產者將太陽能轉為化學能，製造有機養分，是食物來源的基礎。','太陽能輸入、生產者製造有機養分，角色與動作均有中文。',f('養分與能量的來源',[n('太陽能','本題生產者利用的能量來源。','gold'),n('生產者','製造有機養分，儲存化學能。','green')],'生產者轉換能量')),p('② 分解者：讓物質可再利用','分解者分解遺體等有機物，使無機養分回到環境，能再供生產者利用。清除者的協助不能取代這個功能。','生物遺體經分解者轉成無機養分、供生產者再利用的流程。',f('物質循環的重要步驟',[n('生物遺體等有機物'),n('分解者','分泌酵素分解、吸收利用。'),n('無機養分','回到環境，再供生產者吸收。','green')],'分解與回收物質')),p('③ 消費者與清除者，不一定另有','在這個基本循環中，不一定另需取食其他生物的消費者或協助處理遺體的清除者，因此選B。','消費者與清除者的功能及本題必要性直接標示，未把清除者當分解者。',b('B的兩個角色',[n('消費者','取食其他生物。'),n('清除者','取食或處理遺體，協助分解。','gold')],'基本循環不一定另需這兩類','對照生產與分解功能'))],'答案 B：消費者、清除者',['本題基本功能：製造養分＋分解回收。','清除者協助分解，不能取代分解者。','清除者也是一類消費者，四欄功能非全互斥。'],['生產者','消費者','分解者','清除者','有機養分','無機養分','物質循環'],'本題要辨四種功能及基本物質循環，採可選取中文HTML角色/物質/作用流程，直接看見能量來源與物質回收，避免生圖猜分類或只用顏色代表角色。')
elif i=='q-966':
 s(i,'螳螂的位置，要從植物開始數',[p('① 蟬吸植物汁液，是初級消費者','植物自行製造有機養分，是生產者。蟬直接取食植物汁液，所以是初級消費者。','植物與蟬標明生產者及初級消費者，箭頭表示食物能量傳遞。',f('食物鏈的起點',[n('植物｜生產者','製造有機養分。','green'),n('蟬｜初級消費者','吸食植物汁液。')],'食物中的物質與能量傳向取食者')),p('② 螳螂吃蟬，是次級消費者','原文「螳螂方欲食蟬」，螳螂吃的是初級消費者，因此是次級消費者，選C。','蟬被螳螂捕食，箭頭由蟬指向螳螂，文字標明級別。',f('本題所問的角色',[n('蟬｜初級消費者'),n('螳螂｜次級消費者','取食初級消費者。','green')],'被吃者的能量傳向取食者')),p('③ 黃雀在後，才到三級','黃雀取食螳螂，所以在這條簡化食物鏈中是三級消費者。級別依食物來源判斷，不是依故事的出場順序。','螳螂到黃雀的箭頭由食物指向取食者，未反轉。',f('接續到黃雀',[n('螳螂｜次級消費者'),n('黃雀｜三級消費者','取食次級消費者。','gold')],'被吃者的能量傳向取食者'))],'答案 C：次級消費者',['植物→蟬→螳螂→黃雀。','初級直接吃生產者，次級吃初級。','箭頭由食物指向取食者，表示能量流向。'],['初級消費者','次級消費者','三級消費者','生產者','螳螂','黃雀','植物汁液'],'考點是食物鏈級別與能量箭頭，採精確中文HTML鏈條，把每種生物/角色/箭頭動作直接標出，比動漫捕食場景更能避免數錯階層或反畫箭頭。')
elif i=='q-967':
 s(i,'比受益、受害，找差異最大的關係',[p('① 題幹：白蟻與鞭毛蟲都受益','依題幹設定，鞭毛蟲協助消化木材、提供養分；白蟻提供棲所與食物來源。雙方受益，是互利共生。','白蟻與鞭毛蟲各自得到的利益及＋／＋明確標示。',b('題幹｜互利共生（＋／＋）',[n('白蟻｜受益＋','獲得可利用的養分。','green'),n('鞭毛蟲｜受益＋','獲得棲所與食物來源。','green')],'雙方受益','合併雙方結果')),p('② B寄生：一方受益、一方受害','冬蟲夏草菌從蝙蝠蛾幼蟲取得養分，幼蟲受害。這是寄生，和雙方受益的反差最大。','真菌受益＋、幼蟲受害－及寄生關係直接標示。',b('B｜寄生（＋／－）',[n('冬蟲夏草菌｜受益＋','由幼蟲取得養分。'),n('蝙蝠蛾幼蟲｜受害－','受感染、被利用養分。','gold')],'與互利共生的差異最大','比較利害方向')),p('③ A不同但非最大；C、D仍互利','附生蘭花受益，大樹通常無明顯影響，是片利共生。珊瑚與藻類、螞蟻與蚜蟲，在本題都依互利模型判斷。','A片利＋／0、C-D互利＋／＋以文字列出，符號有圖例。',b('其餘三個選項',[n('A｜蘭花＋／大樹0','片利共生：一方受益，另一方無明顯影響。'),n('C｜石珊瑚＋／藻類＋','共生藻提供養分，珊瑚提供棲所等。','green'),n('D｜螞蟻＋／蚜蟲＋','螞蟻取得蜜露，蚜蟲獲得保護。','green')],'不是只找不同，要比差異最大','與題幹利害關係比較'))],'答案 B：冬蟲夏草菌與蝙蝠蛾幼蟲',['＋受益；－受害；0無明顯影響。','題幹互利＋／＋，B寄生＋／－反差最大。','A雖非互利，但反差不如一方受害。'],['白蟻','鞭毛蟲','互利共生','片利共生','冬蟲夏草菌','蝙蝠蛾幼蟲','螞蟻與蚜蟲','差異最大'],'本題比較物種間的＋／＋、＋／0、＋／－，採有中文角色與符號圖例的HTML關係圖，讓受益/受害精確可核，不由生圖猜白蟻腸內機制。')
elif i=='q-970':
 s(i,'稻田中的物質，經哪個組織運送？',[p('① 鴨子幫農耕，仍是消費者','鴨子吃害蟲與雜草，不會自行製造有機養分；主要排出的含氮廢物是尿酸，不是尿素。','鴨的攝食角色、鳥類含氮廢物兩事分開標示。',b('A、B：分清角色與排泄',[n('鴨子｜消費者','以其他生物為食，非生產者。'),n('鳥類主要含氮廢物｜尿酸','不是尿素。','gold')],'幫助稻田，不改變基本生理角色','核對原題兩項敘述')),p('② 水與無機養分，經木質部','根吸收水及溶在水中的無機養分後，經木質部送往莖、葉。糞便等有機物須先經分解，不能原封不動進入木質部。','根吸收、木質部輸導、莖葉接收的方向與物質直接標示。',f('C：水與無機養分的運輸',[n('根｜吸收水與無機養分'),n('木質部｜向上輸導','運送至莖、葉。','green'),n('莖、葉｜獲得所需物質')],'水與無機養分往上運送')),p('③ 韌皮部運有機養分；多物種是群集','糖類等有機養分主要由韌皮部運送。田裡有水稻、鴨、青蛙等不同物種，應稱群集，不是單一族群。','韌皮部運糖及同種族群/多種群集分別中文標明。',b('再分清兩組概念',[n('韌皮部｜主要運送有機養分','不同於木質部的主要輸送物質。'),n('同種｜族群；不同種族群合起來｜群集','本題多種生物屬群集。','gold')],'原題只有C敘述正確','逐項比較'))],'答案 C：由木質部運輸',['木質部主要運水和無機養分。','鴨是消費者，主要含氮廢物為尿酸。','多種生物的族群集合為群集。'],['消費者','生產者','含氮廢物','尿酸','尿素','木質部','韌皮部','無機養分','有機養分','族群','群集'],'此題橫跨攝食角色、含氮廢物、維管束與群集，精確中文HTML把物質/組織/方向明示，比泛稻田動漫更直接呈現C的運輸機制與其他選項差異。')
elif i=='q-971':
 s(i,'中心中空，外圍輸導系統仍可能運作',[p('① 中空不等於所有輸導都消失','本題B的表層，指相對於中心心材而言的外圍輸導區；不是說最外層樹皮都負責運輸。','由外向內的位置順序明示，箭頭不是運輸方向。',f('樹幹外圍到中心｜位置示意',[n('韌皮部｜靠近樹皮內側','主要輸送有機養分。'),n('木質部邊材｜較靠外的木質部','仍可輸水與無機養分。','green'),n('中心心材｜本題已中空','不是主要輸水區。','gold')],'向樹幹中心比較位置','這是位置順序，非水或糖的運輸箭頭。')),p('② 能輸導，不等於細胞都活著','木質部主要輸水的成熟導管、假導管是死細胞；木質部也有活薄壁細胞。不能把木質部一概說成全活或全死。','成熟導管/假導管死細胞與活薄壁細胞有清楚中文標示。',b('木質部中的不同細胞',[n('成熟導管、假導管｜死細胞','主要負責水分輸導。'),n('薄壁細胞｜活細胞','具儲存等功能。','green')],'是否活著，與輸導功能須分辨','比較組成細胞')),p('③ 牛樟芝是真菌，不是生產者','牛樟芝有菌絲，屬多細胞真菌，可分解利用木材中的有機物。藥用價值不會讓它成為生產者。','牛樟芝的多細胞/菌絲/分解者角色明確標示，不將表層全稱活組織。',f('C、D：真菌的分類與角色',[n('牛樟芝｜具菌絲的多細胞真菌'),n('利用木材有機物｜分解者','不是自行製造有機養分的生產者。','gold')],'依取養方式判生態角色'))],'答案 B：外圍仍有輸導組織，可維持存活',['外側邊材輸水，韌皮部主要運有機養分。','成熟導管/假導管是死細胞，木質部另有活薄壁細胞。','中空仍可能存活，不表示破壞樹幹無害。'],['輸導組織','木質部','韌皮部','有機養分','無機養分','成熟導管','假導管','死細胞','活薄壁細胞','牛樟芝','多細胞真菌'],'本題核心是樹幹層次/輸導功能與活死細胞限制，採精確中文HTML位置流程及細胞比較，不讓生圖猜解剖層序。每個箭頭說明是向內位置或功能判斷，與實際輸水方向分開。')
elif i=='q-972':
 s(i,'都卵生，不代表受精方式相同',[p('① 綠蠵龜：體內受精，再產卵','綠蠵龜是爬蟲類，雌雄交配後在雌體內受精，再到沙灘產卵。卵生是在說胚胎發育方式，不能直接等同體外受精。','龜體內受精與上岸產卵以先後流程標示，不畫錯精卵位置。',f('綠蠵龜｜體內受精、卵生',[n('雌體內｜精卵結合','受精發生於雌體內。','green'),n('沙灘上｜產卵','受精後產下卵。')],'受精後再產卵')),p('② 土魠魚：體外受精，仍屬卵生','土魠魚在水中體外受精，也屬卵生。C把龜、魚都說成體外受精，錯在綠蠵龜的受精方式，故應選C。','土魠魚的體外受精與龜體內受精形成中文比較。',b('C：共同卵生，但受精不同',[n('綠蠵龜｜體內受精','爬蟲類，卵生。','green'),n('土魠魚｜體外受精','本題魚種，卵生。','gold')],'不能把兩者都說成體外受精','比較精卵結合位置')),p('③ 其餘三項都正確，不選','蟹與龍蝦是會蛻殼的節肢動物；珊瑚與水母是刺絲胞動物；同一海域不同物種的族群合起來是群集。','A甲殼類蛻殼、B刺絲胞分類、D群集各直接標示。',b('核對A、B、D',[n('A｜蟹、龍蝦','外骨骼，成長須蛻殼。'),n('B｜珊瑚、水母','同屬刺絲胞動物。','green'),n('D｜同海域多種生物','不同物種的族群共同組成群集。','gold')],'本題問錯誤，這三項不選','逐項核對'))],'答案 C：錯把綠蠵龜說成體外受精',['龜體內受精；土魠魚體外受精。','兩者皆卵生，受精方式仍有差別。','不同物種的族群合起來稱群集。'],['綠蠵龜','土魠魚','體內受精','體外受精','卵生','節肢動物','刺絲胞動物','族群','群集','外骨骼'],'本題要精確區分精卵結合位置/產卵/分類與群集，採中文HTML流程及比較框，直接標內外位置與角色，避免生圖暗示龜在海水中排卵受精或所有魚都同一方式。')
else:raise ValueError(i)
